import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for cosine similarity and loss computation
cosine_sim_loss_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void cosine_sim_loss_kernel(const float* predictions, const float* targets, float* out, int batch_size, int vec_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float dot_product = 0.0f;
        float norm_predictions = 0.0f;
        float norm_targets = 0.0f;

        for (int i = 0; i < vec_size; ++i) {
            float p = predictions[idx * vec_size + i];
            float t = targets[idx * vec_size + i];
            dot_product += p * t;
            norm_predictions += p * p;
            norm_targets += t * t;
        }

        norm_predictions = sqrtf(norm_predictions);
        norm_targets = sqrtf(norm_targets);

        float cosine_sim = dot_product / (norm_predictions * norm_targets);
        out[idx] = 1.0f - cosine_sim;
    }
}

torch::Tensor cosine_sim_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int vec_size = predictions.size(1);
    auto out = torch::zeros({batch_size}, predictions.options());

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    cosine_sim_loss_kernel<<<num_blocks, block_size>>>(predictions.data_ptr<float>(), targets.data_ptr<float>(), out.data_ptr<float>(), batch_size, vec_size);

    return out;
}
"""

cosine_sim_loss_cpp_source = (
    "torch::Tensor cosine_sim_loss_cuda(torch::Tensor predictions, torch::Tensor targets);"
)

# Compile the inline CUDA code for cosine similarity and loss computation
cosine_sim_loss = load_inline(
    name="cosine_sim_loss",
    cpp_sources=cosine_sim_loss_cpp_source,
    cuda_sources=cosine_sim_loss_source,
    functions=["cosine_sim_loss_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cosine_sim_loss = cosine_sim_loss

    def forward(self, predictions, targets):
        loss = self.cosine_sim_loss.cosine_sim_loss_cuda(predictions, targets)
        return torch.mean(loss)
